pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {AirDropContract} from "../src/AirDropContract.sol";

contract InvMutTest is Test {
    AirDropContract c;
    function setUp() public { c = new AirDropContract(); }

    function testFuzz_property(address filler, address[] memory tos, uint256[] memory vs) public {
        vm.assume(tos.length > 0);
        vm.assume(vs.length > 0);
        vm.assume(tos.length == vs.length);

        CalleeAccepting callee = new CalleeAccepting();

        address[] memory routedTos = new address[](tos.length);
        for (uint i = 0; i < tos.length; i++) routedTos[i] = address(callee);

        bool ok;
        try c.transfer(address(0), routedTos, vs) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}

contract CalleeAccepting {
    fallback() external payable {
    }
